import{_ as e,o as i,c as o,a0 as r}from"./chunks/framework.TJhnt8t4.js";const j=JSON.parse('{"title":"Model pretnji","description":"","frontmatter":{},"headers":[],"relativePath":"sr/guide/threat-model.md","filePath":"sr/guide/threat-model.md"}'),n={name:"sr/guide/threat-model.md"};function t(s,a,p,k,u,l){return i(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="model-pretnji" tabindex="-1">Model pretnji <a class="header-anchor" href="#model-pretnji" aria-label="Permalink to &quot;Model pretnji&quot;">​</a></h1><p>Svaki put kada mobilna aplikacija pošalje zahtev ka API-ju, ona to radi u okruženju koje programer ne kontroliše. Korisnik se može nalaziti na javnom Wi-Fi-ju aerodroma, njegov saobraćaj može ići kroz korporativni proksi koji terminira HTTPS, ili kroz rootovan uređaj sa instaliranim trećim sertifikatom. U svakom od ovih scenarija, saobraćaj aplikacije je potencijalno dostupan trećim licima — ovo je standardni model pretnji za svaku klijent-server aplikaciju, a ne ivični slučaj.</p><p>Uobičajeno je smatrati da je HTTPS rešen problem zaštite prenosa podataka. Ovo je tačno samo delimično: HTTPS garantuje šifrovanje i autentičnost servera, ali samo u granicama poverenja javne CA infrastrukture — a ta infrastruktura je šira nego što većina programera misli. Podrazumevano skladište korenskih sertifikata na Android uređaju veruje više od 130 CA. Bilo koji od njih može izdati validan sertifikat za vaš domen. Ako je makar jedan kompromitovan — ili je korisnik instalirao neovlašćen korenski sertifikat, namerno ili ne — veza koja izgleda bezbedno, to zapravo nije.</p><h2 id="vektori-napada" tabindex="-1">Vektori napada <a class="header-anchor" href="#vektori-napada" aria-label="Permalink to &quot;Vektori napada&quot;">​</a></h2><h3 id="injekcija-prilagođeni-korenski-ca" tabindex="-1">Injekcija (prilagođeni korenski CA) <a class="header-anchor" href="#injekcija-prilagođeni-korenski-ca" aria-label="Permalink to &quot;Injekcija (prilagođeni korenski CA)&quot;">​</a></h3><p>Najrasprostranjeniji napad na HTTPS saobraćaj mobilnih aplikacija i najjednostavniji za izvođenje: ne zahteva mrežne privilegije niti kompromitaciju infrastrukture — dovoljan je fizički ili udaljeni pristup uređaju.</p><p>Napad koristi osnovno svojstvo PKI-ja: OS veruje svakom sertifikatu koji je potpisao CA iz njegovog korenskog skladišta. Napadač generiše sopstveni korenski sertifikat, instalira ga u pouzdano skladište uređaja, i od tog trenutka može izdavati sertifikate za bilo koji domen koje će OS smatrati validnim. Uređaj se povezuje na proksi napadača, koji klijentu predstavlja &quot;validan&quot; sertifikat potpisan instaliranim CA, a pravom serveru se predstavlja kao običan klijent. Ceo saobraćaj kroz kanal — zaglavlja, tokeni, tela zahteva — vidljiv je u otvorenom obliku. Alati poput Charles Proxy, Burp Suite i mitmproxy automatizuju ceo proces (generisanje CA, instalacija, presretanje saobraćaja u realnom vremenu) za nekoliko minuta.</p><p>Pre Android 7.0 (API 24) aplikacije su podrazumevano verovale korisničkim CA. Počev od Android 7.0, aplikacije ne veruju korisničkim CA osim ako programer to eksplicitno ne dozvoli u <code>network_security_config.xml</code> — za obične korisnike ovo zatvara površinu napada, ali ne i za rootovane uređaje, gde se korisnički sertifikat i dalje može premestiti u sistemsko skladište.</p><h3 id="kompromitacija-sertifikacionog-tela-rogue-ca" tabindex="-1">Kompromitacija sertifikacionog tela (rogue CA) <a class="header-anchor" href="#kompromitacija-sertifikacionog-tela-rogue-ca" aria-label="Permalink to &quot;Kompromitacija sertifikacionog tela (rogue CA)&quot;">​</a></h3><p>Za razliku od injekcije, ovde uopšte nije potreban pristup uređaju žrtve. Kompromitacija CA omogućava napadaču da izda kriptografski validan sertifikat za bilo koji domen — takav koji će prihvatiti svaki uređaj koji veruje tom CA.</p><p><strong>Incident sa DigiNotar-om (2011)</strong> ostaje najilustrativniji primer: holandski CA je hakovan, napadači su izdali preko 500 lažnih sertifikata, uključujući wildcard za <code>*.google.com</code>, koji je korišćen za presretanje HTTPS saobraćaja ka Google servisima kod otprilike 300.000 korisnika, pretežno u Iranu. Čim je ovo otkriveno, svi veći pregledači i OS su povukli poverenje DigiNotar-u; kompanija je bankrotirala u roku od nekoliko nedelja. (<a href="https://en.wikipedia.org/wiki/DigiNotar" target="_blank" rel="noreferrer">više</a>)</p><p>Manje očigledna površina napada je sama procedura Domain Control Validation (DCV), kojom CA potvrđuje da podnosilac zahteva kontroliše domen. Jedan od istorijskih metoda oslanjao se na email adresu iz WHOIS zapisa domena, a ti podaci mogu biti zastareli, kompromitovani ili javno dostupni. U decembru 2024. SSL.com je napustio ovaj metod upravo iz tih razloga. (<a href="https://www.securityweek.com/" target="_blank" rel="noreferrer">više</a>)</p><h3 id="mitm-preko-lazne-pristupne-tacke-evil-twin" tabindex="-1">MITM preko lažne pristupne tačke (Evil Twin) <a class="header-anchor" href="#mitm-preko-lazne-pristupne-tacke-evil-twin" aria-label="Permalink to &quot;MITM preko lažne pristupne tačke (Evil Twin)&quot;">​</a></h3><p>Za Evil Twin napad potreban je samo laptop i Wi-Fi adapter na javnom mestu. Većina uređaja se automatski povezuje na poznate SSID-ove; napadač podigne pristupnu tačku sa imenom legitimne mreže (<code>Airport_Free_WiFi</code>, <code>Starbucks</code>) i jačim signalom, i uređaji u dometu se automatski ponovo povežu. Od tog trenutka sav saobraćaj ide kroz napadača.</p><p>Sam Evil Twin omogućava presretanje samo na mrežnom nivou — za dešifrovanje HTTPS-a potrebno je dodatno povezati rogue CA ili ranjivost u proveri sertifikata u aplikaciji. Godine 2024. australijska Savezna policija je optužila osobu koja je izvodila Evil Twin napade na domaćim letovima i na aerodromima: prikupljao je kredencijale putnika koji su otvarali stranice za prijavu u pregledaču — mobilne aplikacije sa ispravnom proverom sertifikata nisu bile pogođene. (<a href="https://www.afp.gov.au/" target="_blank" rel="noreferrer">više</a>)</p><p>Zašto je ovo posebno važno za mobilne aplikacije: korisnik ne vidi kroz koju pristupnu tačku ide saobraćaj, a aplikacije neprekidno rade u pozadini (sinhronizacija, analitika, push obaveštenja). Čak i kratkotrajno povezivanje na lažnu pristupnu tačku može dovesti do curenja tokena za autorizaciju, ako aplikacija proverava <em>identitet sertifikata</em>, a ne identitet ključa.</p><h3 id="bgp-hijacking-lazni-sertifikat" tabindex="-1">BGP hijacking + lažni sertifikat <a class="header-anchor" href="#bgp-hijacking-lazni-sertifikat" aria-label="Permalink to &quot;BGP hijacking + lažni sertifikat&quot;">​</a></h3><p>BGP hijacking radi na nivou globalnog rutiranja interneta, ne zahteva fizičku blizinu žrtvi i može odjednom pogoditi sve korisnike servisa. BGP nema ugrađenu kriptografsku proveru najava ruta — napadač sa pristupom BGP ruteru može najaviti kraću putanju do ciljnog opsega IP adresa, i deo globalnog saobraćaja počinje da ide kroz njega.</p><p>Samo presretanje je beskorisno protiv šifrovanih veza. Tu u igru ulazi <code>http-01</code> validacija ACME-a: CA šalje HTTP zahtev na IP adresu domena i očekuje određen token u odgovoru. Ako je napadač presreo rutu do tog IP-ja, zahtev stiže njemu, on vrati ispravan token i dobije validan sertifikat za domen koji ne poseduje.</p><p><strong>Incident sa Amazon Route 53 (2018)</strong>: napadači su presreli BGP rute ka DNS serverima Route 53 na otprilike dva sata, ciljajući <code>myetherwallet.com</code>. Podmetnuli su IP adresu u odgovorima, predstavljajući unapred pribavljen validan SSL sertifikat — korisnici su videli ispravnu adresu i zatvoren katanac. Ukradeno je oko 17 miliona dolara u kriptovaluti. (<a href="https://www.internetsociety.org/" target="_blank" rel="noreferrer">više</a>) Sa strane klijenta sve izgleda legitimno — DNS se ispravno razrešava, sertifikat je validan, handshake prolazi uspešno. Jedina pouzdana zaštita na strani klijenta je unapred znati tačno koji javni ključ server treba da predstavi, i odbaciti sve ostalo.</p><h3 id="ssl-stripping" tabindex="-1">SSL stripping <a class="header-anchor" href="#ssl-stripping" aria-label="Permalink to &quot;SSL stripping&quot;">​</a></h3><p>Ako napadi iznad podmeću ili falsifikuju sertifikate, SSL stripping u potpunosti uklanja šifrovanje, tako da nema šta da se razbije. Javno demonstrirao Moxie Marlinspike na Black Hat 2009. alatom <code>sslstrip</code>: korisnik zatraži <code>example.com</code> bez šeme, server redirektuje na HTTPS, a MITM presreće taj redirekt — uspostavljajući HTTPS sa pravim serverom samostalno, dok klijentu i dalje servira običan HTTP.</p><p>Za razliku od pregledača, mobilne aplikacije nemaju adresnu traku, pa korisnik ne vidi pogrešnu šemu. Pre Android 9 (API 28) cleartext saobraćaj je bio podrazumevano dozvoljen; od tada je podrazumevano blokiran, ali programeri ga često ponovo uključuju u <code>network_security_config.xml</code> radi debagovanja ili legacy zavisnosti i zaborave da ga uklone pre izdanja. <code>WebView</code> je posebna površina napada: nasleđuje ponašanje pregledačkog engine-a, uključujući praćenje HTTP redirekata, i u potpunosti je ranjiv ako nije eksplicitno podešen da prinudno koristi HTTPS.</p><p>HSTS (HTTP Strict Transport Security) delimično ublažava problem — kada klijent jednom vidi HSTS zaglavlje preko bezbedne veze, automatski nadograđuje naredne zahteve — ali samo ako je <em>prva</em> veza bila bezbedna (Trust On First Use jaz). Certificate Transparency ovde takođe ne pomaže: u vezi sa uklonjenim SSL-om sertifikata uopšte nema, nema šta da se loguje.</p><h2 id="zasto-staticki-pinning-nije-dovoljan" tabindex="-1">Zašto statički pinning nije dovoljan <a class="header-anchor" href="#zasto-staticki-pinning-nije-dovoljan" aria-label="Permalink to &quot;Zašto statički pinning nije dovoljan&quot;">​</a></h2><p>Klasični SSL pinning ušiva SHA-256 heš javnog ključa servera direktno u binarni fajl aplikacije. Ovo zatvara sve vektore napada iznad — klijent više ne veruje hijerarhiji CA, veruje jednom konkretnom ključu. Ali ovo stvara operativni problem: svaka rotacija sertifikata na serveru zahteva novo izdanje aplikacije, pregled u prodavnici i čekanje da se korisnici ažuriraju. Pri hitnoj rotaciji ključa, deo korisničke baze gubi pristup servisu danima.</p><p>Obilazna rešenja — pinovanje intermedijarnog CA umesto krajnjeg sertifikata, ili skup od više pinova — ili slabe bezbednosnu garanciju, ili zahtevaju strogu koordinaciju između timova. Mehanizmi opoziva (CRL, OCSP) takođe ne pomažu: keširaju se satima i rade fail-open kada nisu dostupni.</p><p>Alternativa — opisana u odeljku <a href="./architecture">Arhitektura</a> — izneti registar pinova potpuno van binarnog fajla: aplikacija dobija aktuelan spisak pouzdanih ključeva sa namenskog endpointa, server ažurira taj registar u realnom vremenu, a jedino što ostaje ušiveno je javni ključ potreban za proveru potpisa registra.</p>',28)])])}const v=e(n,[["render",t]]);export{j as __pageData,v as default};
